use account_realloc_program_client;
use clap::Args;
use clap::Subcommand;
use serde_json::Value;
use serde_json::json;
use solana_sdk::pubkey::Pubkey;

use crate::context::CliContext;
use crate::context::CliError;

#[derive(Debug, Subcommand)]
pub enum Command {
	/// A compact account whose active values occupy only the bytes they need.
	Sample(SampleArgs),
}

#[derive(Debug, Args)]
pub struct SampleArgs {
	/// Account address; overrides PDA derivation.
	#[arg(long)]
	address: Option<String>,
	/// PDA seed `authority`.
	#[arg(long)]
	authority: Option<String>,
}

pub(crate) fn run(context: &CliContext, command: Command) -> Result<(), CliError> {
	match command {
		Command::Sample(args) => fetch_sample(context, args),
	}
}

fn fetch_sample(context: &CliContext, args: SampleArgs) -> Result<(), CliError> {
	let address = match &args.address {
		Some(value) => CliContext::pubkey("--address", value)?,
		None => {
			let authority = match &args.authority {
				Some(value) => CliContext::pubkey("--authority", value)?,
				None => {
					return Err(CliError::MissingSeed {
						account: "sample".to_string(),
						seed: "--authority".to_string(),
					});
				}
			};
			let seeds: &[&[u8]] = &["sample".as_bytes(), authority.as_ref()];
			Pubkey::find_program_address(seeds, &context.program_address).0
		}
	};
	let data = context.fetch_account(&address)?;
	let value = match account_realloc_program_client::accounts::Sample::from_bytes(&data) {
		Ok(account) => sample_json(&account),
		Err(error) => {
			return Err(CliError::AccountDecode {
				address: address.to_string(),
				message: error.to_string(),
			});
		}
	};
	print_value(context.json, "sample", &address, &value);
	Ok(())
}

fn sample_json(account: &account_realloc_program_client::accounts::SampleRef<'_>) -> Value {
	json!({
		"bump": account.bump,
		"authority": account.authority.to_string(),
		"values": account.values().iter().map(|value| value.get()).collect::<Vec<_>>(),
	})
}

fn print_value(json_output: bool, name: &str, address: &Pubkey, value: &Value) {
	if json_output {
		println!(
			"{}",
			serde_json::to_string_pretty(value).unwrap_or_default()
		);
		return;
	}

	println!("{name} {address}");
	if let Some(fields) = value.as_object() {
		for (key, value) in fields {
			println!("  {key}: {value}");
		}
	}
}
